def F(fid,field,question,value,quote,page=1,region='body',critical=True,answer='present',basis='source_text'):
 d=ROOT/fid; pages=json.loads((d/'page-map.json').read_text())['original_physical_pages']
 native=(d/f'native-page-{page}.txt').read_text()
 # Exact embedded-text span where available; scans use source-image transcription.
 if basis=='source_text' and quote and native.strip():
  pattern=re.escape(quote).replace(r'\ ',r'\s+')
  m=re.search(pattern,native)
  if m: quote=m[0]
  else: raise ValueError((fid,field,quote))
 return {'field_id':field,'question':question,'expected_value':value,'answerability':answer,'critical':critical,
 'original_page':pages[page-1],'input_page':page,'region':region,'source_quote':quote,'basis':basis}
